SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/jiuwudaishi-115-luyankou-defense/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002726；EPUB电子本，纸本及异文待核", "id": "cdf3557b-ad52-58db-a213-0692004a273f"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/jiuwudaishi-115-nominations-955/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002720；EPUB电子本，纸本及异文待核", "id": "28e53319-e62d-5b84-b161-025c2d3f458b"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/jiuwudaishi-115-remonstrance-date/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002721；EPUB电子本，纸本及异文待核", "id": "a9f1d101-4a9d-5301-b900-8a3af6cd76b7"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/jiuwudaishi-115-remonstrance-edict/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002724；EPUB电子本，纸本及异文待核", "id": "ca782b49-d7bc-5e1d-be29-58852177e780"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ff2825de598cdd120a803b4e1262b653a990b093/content/books/zizhi-tongjian/vol-292/year-0955/part-01/sources/library/tongjian-292-955-february/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003468；电子底本待考，分段待核", "id": "abc8b9bf-3ba7-5530-8dcc-e609704d6924"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cd645e3efcb32aa415b690b609c4d750baa3dbf6/content/books/zizhi-tongjian/vol-292/year-0954/part-04/sources/library/tongjian-292-954-hunan-yearend/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003467；电子底本待考，分段待核", "id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"title": "宋史·卷271·张藏英传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a03e158968cf63490b7ea1d52bdaea928e33b44d/content/books/zizhi-tongjian/vol-291/year-0953/part-03/sources/library/songshi-271-zhangcangying/source.txt", "note": "《宋史》卷271·张藏英传，段落 songshi-9c6e46fee832-p058967；已核上下文及传主，纸本及异文待核。", "id": "8edcec80-faf6-5c90-95af-0feefd563eee"}]'::jsonb)
