INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}, {"name": "折德扆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "折从远（后名折从阮）之子，任府州蕃汉马步都指挥使。950年五月己亥获任府州团练使，《宋史》也明确记其父为从阮。生卒年未载。", "biography": null, "status": "draft", "id": "11515d9f-5a90-5398-9366-6f44b89ca847"}, {"name": "齐藏珍", "aliases": ["齊藏珍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将军。948年正月与王景崇率禁军迎接回鹘贡使并经略关西。其后建议杀赵思绾，王景崇没有听从。生卒年未载。", "biography": null, "status": "draft", "id": "654b2549-6bd7-5790-80f4-0c95bd3781b3"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "张藏英", "aliases": ["張藏英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州范阳人，契丹军使，兼任榷盐制置等职。953年率军士、亲属、盐户等归附后周。《通鉴》电子本户台与旧史卢台、宋传盧䑓写法有别，按同人同役保留校核说明。生卒年留待后续逐段补录。", "biography": null, "status": "draft", "id": "f4a79754-77c7-514a-a927-bc9d261e9a40"}, {"name": "孟仁毅", "aliases": ["孟仕毅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟昶的弟弟。950年八月获封夔王。《资治通鉴》所用电子本写仕毅，《新五代史》同一夔王写仁毅，按封号和亲属身份对应为同一人，原字保留。生卒年未载。", "biography": null, "status": "draft", "id": "b6e10d68-5fc5-5418-9ac0-31b46f762875"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

