aft", "id": "0568e125-9519-525c-8841-073410c7f23c", "subject_id": "7fd70f38-4db0-55b5-8c24-c14d160858ab", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣令翰林学士及两省官举荐地方官，任命时记录举主姓名。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p004·原文件第36行", "note": "原文：辛卯，初令翰林学士、两省官举令、录。除官之日，仍署举者姓名，；核对说明：令录沿用原官类称谓；只有政策而无本次具名举主名单，不造人物推荐关系。", "status": "draft", "id": "eb72cc10-cbe3-58ae-a054-7b683e312b16", "subject_id": "a6df203b-6446-543f-95d7-11da8fbe0aad", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年正月辛卯", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p004·原文件第36行", "note": "原文：辛卯，初令翰林学士、两省官举令、录。除官之日，仍署举者姓名，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b8dc3068-cd7c-5a6f-a580-822a5423d192", "subject_id": "a6df203b-6446-543f-95d7-11da8fbe0aad", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：命官员举荐令录并记录举主。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p004·原文件第36行", "note": "原文：辛卯，初令翰林学士、两省官举令、录。除官之日，仍署举者姓名，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d4297c59-aa1e-56ba-a489-efacfbdb8ba2", "subject_id": "281778df-3cbd-5b5c-ace8-a6a4d3376721", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同日诏在朝文官各举可任令录者一人，亲族亦可推荐，任命时署举主姓名。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002720；EPUB电子本，纸本及异文待核", "note": "原文：在朝文班，各舉堪為令錄者一人，雖姻族近親，亦無妨嫌。授官之日，各署舉主姓名，；核对说明：《旧五代史》本纪范围写在朝文班，《资治通鉴》为翰林学士与两省官，保留范围详略差别。", "status": "draft", "id": "ce1ca875-7d32-50b5-a844-6bcca3bad9bb", "subject_id": "a6df203b-6446-543f-95d7-11da8fbe0aad", "source_id": "28e53319-e62d-5b84-b161-025c2d3f458b"}, {"subject_table": "event", "field_path": "description", "claim_text": "被荐官员贪污失职时，举荐者须负连带责任。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p004·原文件第36行", "note": "原文：若贪秽败官，并当连坐。；核对说明：这是当时诏令规定，不编造本次已有某人被连坐。", "status": "draft", "id": "2ba7d7f9-c80c-517c-a3bb-cce3976f55e7", "subject_id": "e6e4d656-bb3a-5e52-9e13-17fe7c8151b7", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年正月辛卯", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p004·原文件第36行", "note": "原文：若贪秽败官，并当连坐。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6c3157d4-2eb6-5d73-84c6-e989a5e0808f", "subject_id": "e6e4d656-bb3a-5e52-9e13-17fe7c8151b7", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：规定举主对贪污失职承担连带责任。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p004·原文件第36行", "note": "原文：若贪秽败官，并当连坐。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c74a2e99-c541-5363-aa49-9397390dd04c", "subject_id": "76b80bea-a999-5ada-94df-5b7937fba71d", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》还列不任、懦弱不理的情况，并规定按情节轻重连坐举主。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002720；EPUB电子本，纸本及异文待核", "note": "原文：若在官貪濁不任、懦弱不理，並量事狀重輕，連坐舉主。；核对说明：仅补当时制度适用范围，不转成当代法律规则。", "status": "draft", "id": "977cfd14-4b55-5588-80fc-6825d09840c6", "subject_id": "e6e4d656-bb3a-5e52-9e13-17fe7c8151b7", "source_id": "28e53319-e62d-5b84-b161-025c2d3f458b"}, {"subject_table": "event", "field_path": "description", "claim_text": "后晋后汉以来契丹骑兵深入河北，郊野居民遭杀掠。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p005·原文件第37行", "note": "原文：契丹自晋、汉以来屡寇河北，轻骑深入，无籓篱之限，效野之民每困杀掠。；核对说明：效野疑为郊野，说明采用郊野，引用保持原字；跨朝历次入侵不全绑定为耶律璟个人行为。", "status": "draft", "id": "0543e3e4-70e1-5bd3-9f70-1d4b33f0f84e", "subject_id": "385cc04e-e6bd-518e-972a-7d44418f49b1", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "后晋后汉以来的河北边患回述，具体历次年日未载", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p005·原文件第37行", "note": "原文：契丹自晋、汉以来屡寇河北，轻骑深入，无籓篱之限，效野之民每困杀掠。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "0df270a5-a840-51b2-b44b-12d6ebd05bf0", "subject_id": "385cc04e-e6bd-518e-972a-7d44418f49b1", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "description", "claim_text": "有人建议疏浚深州冀州之间的胡卢河，阻止契丹骑兵奔突。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p005·原文件第37行", "note": "原文：言事者称深、冀之间有胡卢河，横亘数百里，可浚之以限其奔突。；核对说明：建言者匿名，不补姓名；数百里为史载长度，尚无现代线路与坐标校核。", "status": "draft", "id": "18d55c77-d54f-59de-b3e7-2299388c1f5a", "subject_id": "442b80fc-db07-5901-a701-d48ba7be1ee4", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年正月工程诏令以前", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p005·原文件第37行", "note": "原文：言事者称深、冀之间有胡卢河，横亘数百里，可浚之以限其奔突。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "414f63ce-46a5-5958-8541-3f1d4443ecfe", "subject_id": "442b80fc-db07-5901-a701-d48ba7be1ee4", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣命王彦超、韩通率兵夫疏浚胡卢河。", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p005·原文件第37行", "note": "原文：是月，诏忠武节度使王彦超、彰信节度使韩通将兵夫浚胡卢河，；核对说明：命令与数月后的工程成果区分，不把全工程竣工强定在正月。", "status": "draft", "id": "a45c608a-2143-56f5-9c33-6257bd7aa2cd", "subject_id": "5c0b1632-62d1-5c20-98de-a88efe8bc677", "source_id": "6e8d2362-0831-5acb-950a-827627f90a97"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年正月", "citation": "卷292·显德二年（955年正月至二月及相关追述）·zztj-v292-y0955-p005·原文件第37行", "note": "原文：是月，诏忠武节度使王彦超、彰信节度使韩通将兵夫浚胡卢河，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "fa9a49a0-097c-5759-83b0-f21b482968f1", "subject_id": "5c0b1632-62d1-5c20-98de-a88efe8bc677", "source_id": "6e8d2362-0831-5acb-950a-82